      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n가사·간병 서비스 업체 실무자(종사자가 아닌 파견 및 관리 담당자 남성)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.12. 11:40\n조회 15\n구독\n가사·간병 서비스 업체 실무자(종사자가 아닌 파견 및 관리 담당자)\n한국노동연구원 연구과제의 일환으로 진행되는 가사·간병 서비스 업체 실무자 그룹인터뷰 (FGI) 참여자 섭외 가능 여부를 문의드리고자 연락드립니다.\n본 조사는 가사·간병 종사자의 실제 업무 환경과 노무제공 실태를 파악하기 위한 연구로, 관련 업체 및 기관의 운영 실무자들을 대상으로 인터뷰를 진행하고자 합니다.\n1. 조사 개요\n조사 방식: 소규모 그룹인터뷰 (FGI)\n소요 시간: 약 2시간\n참여 사례비: 별도 협의\n진행 일정,장소: 대상자 섭외 후 연구진과 개별 일정 협의\n2. 모집 대상\n가사·간병 서비스 관련 업체 및 기관에서 종사자 매칭·배정, 인력 관리, 계약 및 정산 등의 업무를 수행한 경험이 있는 실무자 또는 운영책임자\n가사/간병서비스 플랫폼 담당자\n간병협회·간병인 소개 및 파견업체\n※ 위 업무를 모두 담당할 필요는 없으며, 관련 업무 경험이 있는 퇴직자도 참여 가능합니다.\n※ 본 인터뷰는 개별 기업의 운영 방식을 평가하기 위한 것이 아니라, 가사·간병 종사자의 실제 업무 환경과 노무제공 실태를 이해하기 위한 연구 목적으로 진행됩니다.\n사례비는 10만원입니다.\n3. 대상자 확인 사항\n섭외 시 아래 내용을 확인 부탁드립니다.\n성함 및 연락처\n업체 유형\n① 가사/간병서비스 플랫폼\n② 직업소개소(파출사무소)\n③ 재가요양센터\n④ 간병협회·간병인 소개 및 파견업체\n업체명\n직급 및 담당 업무\n관련 업무 경력 (근무 기간 포함)\n통화 가능한 시간대\n우선 위 정보를 전달해 주시면 대상자 적합성을 확인한 후, 개별적으로 연락하여 인터뷰 일정 등을 협의할 예정입니다.\nhttps://forms.gle/zYVztLpYDkPeU4S57\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n가사·간병 서비스 업체 실무자(종사자가 아닌 파견 및 관리 담당자 여성)\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n가사·간병 서비스 업체 실무자(종사자가 아닌 파견 및 관리 담당자 남성)\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n급급급) 20~45세 미혼여성) 200만원 상당 리프팅 시술 체험 및 SNS 릴스 촬영 참여자 모집 [사례비: 30만원]\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n급급급) 20~45세 기혼여성) 200만원 상당 리프팅 시술 체험 및 SNS 릴스 촬영 참여자 모집 [사례비: 30만원]\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
