      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n20~49세남성) 내근직 아르바이트 모집\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.12. 15:32\n조회 117\n구독\n11월(바로 출근 가능)~12월 초까지 내근직으로 근무하실 어시스트(주업무: 전화 리쿠르팅) 아르바이트 모집합니다.\n본인이 조사에 신청한 분들께 전화로 리쿠르팅 및 확인 연락, 간단한 엑셀 입력 업무입니다.\n유 경험자 또는 전화업무에 익숙하신 분들\n20~49세남녀) 내근직 아르바이트 모집\n1. 경력\n-무관(신입+경력)\n-전화 업무 가능자\n-간단한 엑셀 입력 가능 한 분. (PC 사용 가능자)\n-주 5일 성실 출근 가능한 분\n2. 성, 연령\n성별무관, 20~49세\n3. 학력\n고졸 이상\n4. 모집직종\n리서치 회사 실사팀 어시스트\n5. 고용형태\n일용직\n6. 모집인원\n1명 이하\n7. 근무 기간 및 시간 / 근무지\n●바로 출근 가능하고 12월초까지 계속 근무 가능자.\n●근무시간 10시~18시 (점심시간 1시간, 가끔 주말,야근 업무 있을 수 있음)\n●근무지: 2호선 충정로역 부근\n프로젝트 종료 후 협의하에 계속 근무 가능\n8. 업무 내용\n- 전화 업무 (참여자 모집 설문 및 전화 확인 업무, 문자 전송 등)\n- 데이터 입력 업무\n- 기타 보조 업무\n9. 급여\n해당년도 최저 시급 책정 (주휴수당, 4대보험)\n10. 우대사항\n동종업계 경력자, 바로 업무가 가능 한 분, 성실한 분, 센스 있으신 분\n11. 신청 양식\n이름/휴대폰번호/성별/만나이/현재직업/리서치회사 내근직 알바 경력(회사+기간, 없으면 없음)/11월초까지 지속 출근 가능 여부\nhttps://forms.gle/acjd2yposqNdyyLm9\n좋아요\n0\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n11월 중순) 만 15~39세 수도권 거주 남녀) 캔디류 맛 테스트\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n20~49세남성) 내근직 아르바이트 모집\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n성남시 아동친화도시 표준조사 온라인 설문조사 -경기도 성남시 분당구에 소재한 초등학교/중학교 학부모\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n고유링크) 3시간 20만) 11/24) 20세 이상 여성 ) 콘텐츠( 다양한 정보성 ) 크리에이터 대상 좌담회\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
