      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 11/30~12/3) LH 국민 인식도 조사: 20대 대학생 또는 대학원생\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.12. 21:44\n조회 50\n구독\n고유링크) 11/30~12/3) LH 국민 인식도 조사: 20대 대학생 또는 대학원생\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n연령 / 쿼터 부분 마감이 있을수 있으니 참고 부탁드립니다~\n- 조사 대상\n1G : 20대 대학생 또는 대학원생\n2G : 취업 준비생 혹은 입사 저연차 (1~2년)인 93-04년생\n3G : 결혼 3년 이내 및 무자녀 혹은 결혼 5년 이내 영유아 자녀가 있는 88~02년생\n4G : 초등생 부모 혹은 중고생 부모인 83~97년생\n5G : 아파트 자가 혹은 아파트 비자가 거주중인 72~82년생\n- 조사 일정 : 11월 30일 (월) ~ 12월 3일 (목)중 하루 / 시간은 추후 안내드립니다\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n소요시간 120분\n사례비 60,000원\n안내사항 해당 조사에서는 LH(한국토지주택공사)에 대해 귀하가 가지고 계신 이미지 및 홍보 방안에 대해 여쭤볼 예정입니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/836?refuser=23341&intro=2\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 11/30~12/3) LH 국민 인식도 조사:취업 준비생 혹은 입사 저연차 (1~2년)인 93-04년생\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n고유링크) 11/30~12/3) LH 국민 인식도 조사: 20대 대학생 또는 대학원생\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n급급급) 2시간 10만)11/24~26) 20~29세 여성) 데님 쟈켓 이나 셔킷자켓 패션 트렌드 조사\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n급급) 2시간 10만) 11/24~26) 30~35세 여성) 데님 쟈켓 이나 셔킷자켓 패션 트렌드 조사\n좌담회알바좌담회카페\n26.11.12.\n댓글\n0\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
